 "content": "def transform(grid):
    """Fill enclosed horizontal gaps and extend each bridge upward as a ray."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    rays = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] != 0:
                c += 1
                continue
            start = c
            while c < w and row[c] == 0:
                c += 1
            # A gap is a bridge only when the same nonzero color borders it.
            if start > 0 and c < w and row[start - 1] != 0 and row[start - 1] == row[c]:
                color = row[start - 1]
                for x in range(start, c):
                    out[r][x] = color
                    rays.append((r, x, color))
    # Each horizontal bridge sends its color upward. Higher bridges naturally
    # replace the ray above them, while the lower ray remains below.
    for r, c, color in sorted(rays, reverse=True):
        for y in range(r):
            out[y][c] = color
    return out
