def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bridges = []
    # Close each single-cell gap between matching horizontal segments.
    for r in range(h):
        for c in range(1, w-1):
            color = grid[r][c-1]
            if color and grid[r][c] == 0 and grid[r][c+1] == color:
                out[r][c] = color
                bridges.append((r,c,color))
    # Extend each horizontal bridge upward, stopping at the next colored bar.
    for r,c,color in sorted(bridges):
        for y in range(r-1,-1,-1):
            if out[y][c]:
                break
            out[y][c] = color
    # Vertical marker strokes also extend upward until they meet a horizontal
    # bar. Markers are isolated single-cell rows; horizontal source rows are
    # excluded so their bridge rays retain their own colors.
    for r in range(h):
        if sum(v != 0 for v in grid[r]) != 1:
            continue
        c = next(i for i,v in enumerate(grid[r]) if v != 0)
        color = grid[r][c]
        y = r-1
        while y >= 0 and out[y][c] == 0:
            out[y][c] = color
            y -= 1
    return out

